/**
 * Minimal, dependency-free ZIP reader/writer for Office Open XML packages.
 *
 * Why hand-rolled instead of a library: every package on the device is loaded
 * from the payload tree, and the Office tool must keep working under
 * `--jitless` (no WebAssembly) with no native addons. A ZIP container is a
 * stable, small format — local file headers + a central directory + one
 * end-of-central-directory record — and Node's built-in `zlib` already gives
 * us raw deflate/inflate, which is compiled C, not WASM. That keeps the tool
 * zero-dependency and auditable.
 *
 * Deliberately unsupported (and rejected with a clear error rather than
 * silently mis-read): ZIP64, encryption, and compression methods other than
 * stored/deflate. Office documents produced by Word/WPS/Excel are ordinary
 * deflate archives; a 4 GB+ document is not a phone workload.
 *
 * All names are validated on both read and write: an entry name may not be
 * absolute, contain `..`, or a NUL. `readZip` never extracts to disk, so the
 * check is defence in depth for callers that later feed a name to a path API.
 */

import zlib from "node:zlib";

import { OfficeError } from "./errors.js";

const SIG_LOCAL = 0x04034b50;
const SIG_CENTRAL = 0x02014b50;
const SIG_EOCD = 0x06054b50;
const FLAG_ENCRYPTED = 0x0001;
const FLAG_UTF8 = 0x0800;
const METHOD_STORE = 0;
const METHOD_DEFLATE = 8;
const MAX_COMMENT = 0xffff;

/** Fixed DOS timestamp (2024-01-01 00:00) so generated archives are deterministic. */
const DOS_TIME = 0;
const DOS_DATE = ((2024 - 1980) << 9) | (1 << 5) | 1;

const CRC_TABLE = (() => {
	const table = new Int32Array(256);
	for (let n = 0; n < 256; n++) {
		let c = n;
		for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
		table[n] = c;
	}
	return table;
})();

/** CRC-32 of a buffer, as required by the ZIP local and central headers. */
export function crc32(buffer) {
	let c = -1;
	for (let i = 0; i < buffer.length; i++) c = CRC_TABLE[(c ^ buffer[i]) & 0xff] ^ (c >>> 8);
	return (c ^ -1) >>> 0;
}

/** Reject archive entry names that could escape a destination directory. */
export function validateEntryName(name) {
	if (typeof name !== "string" || name.length === 0) {
		throw new OfficeError("archive entry has no name", "OFFICE_BAD_ZIP");
	}
	if (name.includes("\0") || name.startsWith("/") || /^[A-Za-z]:[\\/]/.test(name)) {
		throw new OfficeError(`archive entry has an absolute or invalid name: ${name}`, "OFFICE_BAD_ZIP");
	}
	const parts = name.replace(/\\/g, "/").split("/");
	if (parts.some((part) => part === "..")) {
		throw new OfficeError(`archive entry escapes its directory: ${name}`, "OFFICE_BAD_ZIP");
	}
	return name;
}

/** Encode one entry, adding the UTF-8 name flag only when it is needed. */
function nameBytes(name) {
	const bytes = Buffer.from(name, "utf8");
	return { bytes, utf8: bytes.length !== name.length };
}

/**
 * Build a ZIP archive from `{ name, data }` entries.
 * `data` may be a string (UTF-8) or any Buffer/Uint8Array. Names are written in
 * the order given; no compression-level tuning beyond "smaller wins".
 */
export function writeZip(files) {
	if (!Array.isArray(files) || files.length === 0) {
		throw new OfficeError("cannot write an empty archive", "OFFICE_BAD_ZIP");
	}
	const chunks = [];
	const central = [];
	let offset = 0;
	for (const file of files) {
		const name = validateEntryName(file.name);
		const raw = typeof file.data === "string" ? Buffer.from(file.data, "utf8") : Buffer.from(file.data);
		const deflated = zlib.deflateRawSync(raw, { level: 9 });
		const useDeflate = deflated.length < raw.length;
		const body = useDeflate ? deflated : raw;
		const method = useDeflate ? METHOD_DEFLATE : METHOD_STORE;
		const { bytes: encodedName, utf8 } = nameBytes(name);
		const flags = utf8 ? FLAG_UTF8 : 0;
		const crc = crc32(raw);

		const local = Buffer.alloc(30);
		local.writeUInt32LE(SIG_LOCAL, 0);
		local.writeUInt16LE(20, 4);
		local.writeUInt16LE(flags, 6);
		local.writeUInt16LE(method, 8);
		local.writeUInt16LE(DOS_TIME, 10);
		local.writeUInt16LE(DOS_DATE, 12);
		local.writeUInt32LE(crc, 14);
		local.writeUInt32LE(body.length, 18);
		local.writeUInt32LE(raw.length, 22);
		local.writeUInt16LE(encodedName.length, 26);
		local.writeUInt16LE(0, 28);
		chunks.push(local, encodedName, body);

		const entry = Buffer.alloc(46);
		entry.writeUInt32LE(SIG_CENTRAL, 0);
		entry.writeUInt16LE(0x0314, 4);
		entry.writeUInt16LE(20, 6);
		entry.writeUInt16LE(flags, 8);
		entry.writeUInt16LE(method, 10);
		entry.writeUInt16LE(DOS_TIME, 12);
		entry.writeUInt16LE(DOS_DATE, 14);
		entry.writeUInt32LE(crc, 16);
		entry.writeUInt32LE(body.length, 20);
		entry.writeUInt32LE(raw.length, 24);
		entry.writeUInt16LE(encodedName.length, 28);
		entry.writeUInt16LE(0, 30);
		entry.writeUInt16LE(0, 32);
		entry.writeUInt16LE(0, 34);
		entry.writeUInt16LE(0, 36);
		// UNIX mode 0644 in the high half; without it `unzip` creates mode 000
		// files (the archive is still valid to Word, but not to a user).
		entry.writeUInt32LE((0o100644 << 16) >>> 0, 38);
		entry.writeUInt32LE(offset, 42);
		central.push(entry, encodedName);

		offset += local.length + encodedName.length + body.length;
	}

	const centralBuffer = Buffer.concat(central);
	const eocd = Buffer.alloc(22);
	eocd.writeUInt32LE(SIG_EOCD, 0);
	eocd.writeUInt16LE(0, 4);
	eocd.writeUInt16LE(0, 6);
	eocd.writeUInt16LE(files.length, 8);
	eocd.writeUInt16LE(files.length, 10);
	eocd.writeUInt32LE(centralBuffer.length, 12);
	eocd.writeUInt32LE(offset, 16);
	eocd.writeUInt16LE(0, 20);
	return Buffer.concat([...chunks, centralBuffer, eocd]);
}

/** One parsed central-directory entry. */
class Entry {
	constructor(name, flags, method, crc, compressedSize, uncompressedSize, localOffset) {
		this.name = name;
		this.flags = flags;
		this.method = method;
		this.crc = crc;
		this.compressedSize = compressedSize;
		this.uncompressedSize = uncompressedSize;
		this.localOffset = localOffset;
	}
}

/** Random-access view over an in-memory ZIP; entries decompress on first read. */
export class ZipArchive {
	constructor(buffer, entries) {
		this.buffer = buffer;
		this.entries = entries;
		this.cache = new Map();
	}

	/** Every entry name, in central-directory order. */
	names() {
		return [...this.entries.keys()];
	}

	has(name) {
		return this.entries.has(name);
	}

	/** Read one entry's bytes, or `undefined` when the archive does not hold it. */
	read(name) {
		const entry = this.entries.get(name);
		if (entry === undefined) return undefined;
		const cached = this.cache.get(name);
		if (cached !== undefined) return cached;
		const buffer = this.buffer;
		const local = entry.localOffset;
		if (local + 30 > buffer.length || buffer.readUInt32LE(local) !== SIG_LOCAL) {
			throw new OfficeError(`archive entry has a broken local header: ${name}`, "OFFICE_BAD_ZIP");
		}
		const nameLength = buffer.readUInt16LE(local + 26);
		const extraLength = buffer.readUInt16LE(local + 28);
		const start = local + 30 + nameLength + extraLength;
		const end = start + entry.compressedSize;
		if (end > buffer.length) {
			throw new OfficeError(`archive entry is truncated: ${name}`, "OFFICE_BAD_ZIP");
		}
		const body = buffer.subarray(start, end);
		let data;
		if (entry.method === METHOD_STORE) {
			data = Buffer.from(body);
		} else if (entry.method === METHOD_DEFLATE) {
			try {
				data = zlib.inflateRawSync(body);
			} catch (error) {
				throw new OfficeError(`archive entry cannot be inflated: ${name} (${error.message})`, "OFFICE_BAD_ZIP");
			}
		} else {
			throw new OfficeError(`archive entry uses unsupported compression method ${entry.method}: ${name}`, "OFFICE_BAD_ZIP");
		}
		if (data.length !== entry.uncompressedSize) {
			throw new OfficeError(`archive entry has the wrong size: ${name}`, "OFFICE_BAD_ZIP");
		}
		if (crc32(data) !== entry.crc) {
			throw new OfficeError(`archive entry failed its checksum: ${name}`, "OFFICE_BAD_ZIP");
		}
		this.cache.set(name, data);
		return data;
	}

	/** Read one entry as UTF-8 text; `undefined` when absent. */
	text(name) {
		const data = this.read(name);
		return data === undefined ? undefined : data.toString("utf8");
	}
}

/** Locate the end-of-central-directory record, tolerating a trailing comment. */
function findEocd(buffer) {
	const last = buffer.length - 22;
	const first = Math.max(0, last - MAX_COMMENT);
	for (let i = last; i >= first; i--) {
		if (buffer.readUInt32LE(i) !== SIG_EOCD) continue;
		const commentLength = buffer.readUInt16LE(i + 20);
		if (i + 22 + commentLength <= buffer.length) return i;
	}
	throw new OfficeError("not a ZIP archive (no end-of-central-directory record)", "OFFICE_BAD_ZIP");
}

/**
 * Parse a ZIP archive held in memory. The data is not copied; `ZipArchive`
 * reads entry bodies lazily from the supplied buffer.
 */
export function readZip(input) {
	const buffer = Buffer.isBuffer(input) ? input : Buffer.from(input);
	if (buffer.length < 22) throw new OfficeError("not a ZIP archive (too short)", "OFFICE_BAD_ZIP");
	const eocd = findEocd(buffer);
	const disk = buffer.readUInt16LE(eocd + 4);
	const centralDisk = buffer.readUInt16LE(eocd + 6);
	const count = buffer.readUInt16LE(eocd + 10);
	const centralOffset = buffer.readUInt32LE(eocd + 16);
	if (disk !== 0 || centralDisk !== 0) throw new OfficeError("multi-disk ZIP archives are not supported", "OFFICE_BAD_ZIP");
	if (count === 0xffff || centralOffset === 0xffffffff) throw new OfficeError("ZIP64 archives are not supported", "OFFICE_BAD_ZIP");
	if (centralOffset + 46 * count > buffer.length) throw new OfficeError("ZIP central directory is out of bounds", "OFFICE_BAD_ZIP");

	const entries = new Map();
	let position = centralOffset;
	for (let index = 0; index < count; index++) {
		if (position + 46 > buffer.length || buffer.readUInt32LE(position) !== SIG_CENTRAL) {
			throw new OfficeError("ZIP central directory is corrupt", "OFFICE_BAD_ZIP");
		}
		const flags = buffer.readUInt16LE(position + 8);
		const method = buffer.readUInt16LE(position + 10);
		const crc = buffer.readUInt32LE(position + 16);
		const compressedSize = buffer.readUInt32LE(position + 20);
		const uncompressedSize = buffer.readUInt32LE(position + 24);
		const nameLength = buffer.readUInt16LE(position + 28);
		const extraLength = buffer.readUInt16LE(position + 30);
		const commentLength = buffer.readUInt16LE(position + 32);
		const localOffset = buffer.readUInt32LE(position + 42);
		const next = position + 46 + nameLength + extraLength + commentLength;
		if (next > buffer.length) throw new OfficeError("ZIP central directory entry is truncated", "OFFICE_BAD_ZIP");
		if (compressedSize === 0xffffffff || uncompressedSize === 0xffffffff || localOffset === 0xffffffff) {
			throw new OfficeError("ZIP64 entries are not supported", "OFFICE_BAD_ZIP");
		}
		if ((flags & FLAG_ENCRYPTED) !== 0) throw new OfficeError("encrypted ZIP entries are not supported", "OFFICE_BAD_ZIP");
		const name = validateEntryName(buffer.toString("utf8", position + 46, position + 46 + nameLength));
		if (!entries.has(name)) {
			entries.set(name, new Entry(name, flags, method, crc, compressedSize, uncompressedSize, localOffset));
		}
		position = next;
	}
	return new ZipArchive(buffer, entries);
}
